window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 20000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await fn()) return true; await sleep(250) } return false };
window.nav = async (name) => { const b = [...document.querySelectorAll('nav button')].find((x) => x.textContent.trim() === name); if (!b) return 'NO NAV ' + name; b.click(); await sleep(2500); return 'nav ' + name };
window.trigger = () => document.querySelector('button[aria-label^="League: "]');
window.league = () => trigger()?.getAttribute('aria-label')?.replace('League: ', '') ?? null;
window.switchTo = async (name) => { const t = trigger(); if (!t) return 'NO MENU'; t.focus(); t.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await until(() => document.querySelectorAll('[role=menuitemradio]').length > 0, 3000); const item = [...document.querySelectorAll('[role=menuitemradio]')].find((x) => x.textContent.startsWith(name)); if (!item) return 'NO ITEM ' + name; item.click(); await until(() => league() === name, 5000); await sleep(3000); return league() };
window.openData = async () => { const b = [...document.querySelectorAll('nav button')].find((x) => x.title === 'See what is loaded'); if (!b) return 'NO STATUS'; b.click(); await until(() => document.querySelectorAll('section[aria-label] tbody tr').length > 20); await sleep(3000); return 'data open' };
window.section = (name) => document.querySelector('section[aria-label="' + name + '"]');
window.familyRows = (name) => [...(section(name)?.querySelectorAll('tbody tr') ?? [])].map((r) => [...r.querySelectorAll('td')].map((c) => c.textContent.trim()));
window.tierOf = (name, label) => { const s = section(name); if (!s) return null; let tier = null; for (const el of s.querySelectorAll('h3, h4, tbody tr, [class*=uppercase]')) { if (el.tagName !== 'TR' && el.textContent.trim().length < 40) tier = el.textContent.trim(); if (el.tagName === 'TR' && el.textContent.includes(label)) return tier } return null };
